# WARNING: Under review - generated by LLM.

import os
import subprocess
import sys
from importlib import import_module, util
from pathlib import Path

import pytest

from agent import run_and_report, show_interrupted_run, show_run_result

from .tiny_llm_base import ToolPolicy, Workspace, run_agent


def patch_workspace_popen(monkeypatch, replacement):
    """Patch common qualified and directly imported Popen lookup styles."""

    workspace_module = import_module(Workspace.__module__)
    monkeypatch.setattr(subprocess, "Popen", replacement)
    monkeypatch.setattr(workspace_module, "Popen", replacement, raising=False)


def patch_workspace_killpg(monkeypatch, replacement):
    """Patch common qualified and directly imported killpg lookup styles."""

    workspace_module = import_module(Workspace.__module__)
    monkeypatch.setattr(os, "killpg", replacement)
    monkeypatch.setattr(workspace_module, "killpg", replacement, raising=False)


def responses(*items):
    """Test helper for Week 4, Day 7: return scripted model responses."""

    queue = iter(items)
    return lambda messages: next(queue)


@pytest.mark.parametrize(
    ("subcommand", "target"),
    [("test", "tests"), ("test-refsol", "tests_refsol")],
)
def test_canonical_runner_propagates_the_pytest_exit_code(
    monkeypatch, subcommand, target
):
    script = Path(__file__).parents[1] / "scripts" / "dev-tools.py"
    spec = util.spec_from_file_location("week4_dev_tools", script)
    assert spec is not None and spec.loader is not None
    dev_tools = util.module_from_spec(spec)
    spec.loader.exec_module(dev_tools)
    pytest_calls = []
    monkeypatch.setattr(sys, "argv", [str(script), subcommand])
    monkeypatch.setattr(
        dev_tools.pytest,
        "main",
        lambda args: pytest_calls.append(args) or 7,
    )

    with pytest.raises(SystemExit) as stopped:
        dev_tools.main()

    assert stopped.value.code == 7
    assert pytest_calls == [["-v", target]]


def test_capstone_records_a_safe_reviewable_change(tmp_path):
    source = tmp_path / "answer.py"
    source.write_text("ANSWER = 41\n", encoding="utf-8")
    confirmations = []
    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True),
        confirm_tool=lambda action: confirmations.append(action.tool) or True,
    )
    generate = responses(
        '{"tool":"read_file","path":"answer.py"}',
        '{"tool":"edit_file","path":"answer.py","old":"41","new":"42"}',
        '{"final":"updated the answer"}',
    )

    result = run_agent("fix the answer", generate, workspace)

    assert result.completed
    assert result.modified_files == ("answer.py",)
    assert result.task_success is None
    assert not result.command_side_effects_untracked
    assert result.uncertain_modified_files == ()
    assert not result.command_cleanup_incomplete
    assert source.read_text(encoding="utf-8") == "ANSWER = 42\n"
    assert [event.step for event in result.events] == [1, 2, 3]
    assert confirmations == ["edit_file"]


def test_capstone_denied_edit_leaves_the_workspace_unchanged(tmp_path):
    source = tmp_path / "answer.py"
    source.write_text("ANSWER = 41\n", encoding="utf-8")
    workspace = Workspace(ToolPolicy(tmp_path, allow_writes=True))
    generate = responses(
        '{"tool":"read_file","path":"answer.py"}',
        '{"tool":"edit_file","path":"answer.py","old":"41","new":"42"}',
        '{"final":"edit was refused"}',
    )

    result = run_agent("fix the answer", generate, workspace)

    assert result.completed
    assert result.modified_files == ()
    assert result.task_success is None
    assert not result.command_side_effects_untracked
    assert result.uncertain_modified_files == ()
    assert not result.command_cleanup_incomplete
    assert source.read_text(encoding="utf-8") == "ANSWER = 41\n"
    assert result.events[1].result == "error: operator denied edit_file"


def test_capstone_cannot_smuggle_in_a_command(tmp_path, monkeypatch):
    workspace = Workspace(ToolPolicy(tmp_path))
    process_starts = []

    def unexpected_popen(*args, **kwargs):
        process_starts.append((args, kwargs))
        raise AssertionError("a disabled command must not start a process")

    patch_workspace_popen(monkeypatch, unexpected_popen)
    generate = responses(
        '{"tool":"run_command","argv":["tiny-llm-disabled-command-sentinel"]}',
        '{"final":"command was refused"}',
    )

    result = run_agent("inspect the project", generate, workspace)

    assert result.completed
    assert result.events[0].action is None
    assert "not enabled" in result.events[0].result
    assert process_starts == []
    assert not result.command_side_effects_untracked
    assert not result.command_cleanup_incomplete


class _EmptyStdout:
    def read(self, size):
        return b""

    def close(self):
        pass


class _CompletedCommand:
    pid = 24680
    stdout = _EmptyStdout()

    def wait(self, timeout=None):
        return 7

    def kill(self):
        pass


def test_started_command_is_reported_as_untracked_not_validated(
    tmp_path, monkeypatch, capsys
):
    command = ("safe-tool",)
    workspace = Workspace(
        ToolPolicy(tmp_path, allowed_commands=(command,)),
        confirm_tool=lambda action: True,
    )
    killed_groups = []
    patch_workspace_popen(monkeypatch, lambda *args, **kwargs: _CompletedCommand())
    patch_workspace_killpg(
        monkeypatch, lambda pid, sig: killed_groups.append((pid, sig))
    )
    generate = responses(
        '{"tool":"run_command","argv":["safe-tool"]}',
        '{"final":"reported the failed command"}',
    )

    result = run_agent("run the check", generate, workspace)
    show_run_result(result)

    assert result.completed
    assert result.task_success is None
    assert result.command_side_effects_untracked
    assert result.events[0].result == "exit code: 7"
    output = capsys.readouterr().out
    assert "task success not independently validated" in output
    assert "side effects are not included" in output
    assert "Completed:" not in output


def test_interrupted_run_renderer_discloses_uncertain_side_effects(tmp_path, capsys):
    workspace = Workspace(ToolPolicy(tmp_path))
    workspace.command_side_effects_untracked = True
    workspace.command_cleanup_incomplete = True
    workspace.uncertain_modified_files.add(tmp_path / "answer.py")

    show_interrupted_run(workspace)

    output = capsys.readouterr().out
    assert "Stopped: interrupted" in output
    assert "mutation outcome is uncertain" in output
    assert "side effects are not included" in output
    assert "inspect the host for a surviving process" in output


def test_run_result_propagates_and_renders_uncertain_side_effects(tmp_path, capsys):
    workspace = Workspace(ToolPolicy(tmp_path))
    workspace.uncertain_modified_files.add(tmp_path / "answer.py")
    workspace.command_side_effects_untracked = True
    workspace.command_cleanup_incomplete = True

    result = run_agent(
        "report state",
        responses('{"final":"state reported"}'),
        workspace,
    )
    show_run_result(result)

    assert result.uncertain_modified_files == ("answer.py",)
    assert result.command_cleanup_incomplete
    output = capsys.readouterr().out
    assert "mutation outcome is uncertain" in output
    assert "inspect the host for a surviving process" in output


def test_unexpected_run_failure_discloses_prior_side_effects(tmp_path, capsys):
    workspace = Workspace(ToolPolicy(tmp_path))
    workspace.modified_files.add(tmp_path / "answer.py")
    workspace.command_side_effects_untracked = True
    workspace.command_cleanup_incomplete = True

    def fail_after_side_effects():
        raise RuntimeError("backend failed")

    with pytest.raises(RuntimeError, match="backend failed"):
        run_and_report(fail_after_side_effects, workspace)

    output = capsys.readouterr().out
    assert "Stopped: unexpected error" in output
    assert 'Tracked file-tool changes: ["answer.py"]' in output
    assert "side effects are not included" in output
    assert "inspect the host for a surviving process" in output
